package com.church.church_backend;

import java.text.Normalizer;
import java.util.*;
import java.util.stream.Collectors;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/parishes")
public class ParishController {
    private final ParishRepository parishes; private final DeaneryRepository deaneries; private final PriestRepository priests; private final MassTimeRepository massTimes; private final UserRepository users;
    public ParishController(ParishRepository parishes,DeaneryRepository deaneries,PriestRepository priests,MassTimeRepository massTimes,UserRepository users){this.parishes=parishes;this.deaneries=deaneries;this.priests=priests;this.massTimes=massTimes;this.users=users;}

    @GetMapping public List<Map<String,Object>> list(@RequestParam(name="deanery_id",required=false) Long deaneryId,@RequestParam(name="search",required=false) String search){
        List<Parish> rows=deaneryId==null?parishes.findAll():parishes.findByDeaneryId(deaneryId);
        if(!blank(search)){String q=search.trim().toLowerCase(Locale.ROOT);rows=rows.stream().filter(p->p.getName()!=null&&p.getName().toLowerCase(Locale.ROOT).contains(q)).collect(Collectors.toList());}
        return rows.stream().map(this::dto).collect(Collectors.toList());
    }
    @GetMapping("/{id}") public ResponseEntity<?> get(@PathVariable Long id){return parishes.findById(id).<ResponseEntity<?>>map(p->ResponseEntity.ok(dto(p))).orElseGet(()->error(HttpStatus.NOT_FOUND,"Parish not found"));}
    @PostMapping public ResponseEntity<?> create(@RequestBody Parish in){if(blank(in.getName()))return error(HttpStatus.BAD_REQUEST,"Parish name is required");if(parishes.existsByNameIgnoreCase(in.getName().trim()))return error(HttpStatus.CONFLICT,"A parish with this name already exists. Parish names must be unique.");if(in.getDeaneryId()!=null&&!deaneries.existsById(in.getDeaneryId()))return error(HttpStatus.BAD_REQUEST,"Deanery not found");if(!validPriest(in.getParishPriestId())||!validPriest(in.getAssistantPriestId()))return error(HttpStatus.BAD_REQUEST,"Priest IDs must refer to existing priests");if(in.getCatholicCount()!=null&&in.getCatholicCount()<0)return error(HttpStatus.BAD_REQUEST,"catholicCount cannot be negative");Parish p=new Parish();copy(in,p);p.setSlug(uniqueSlug(in.getName(),null));return ResponseEntity.status(HttpStatus.CREATED).body(dto(parishes.save(p)));}
    @PutMapping("/{id}") public ResponseEntity<?> update(@PathVariable Long id,@RequestBody Parish in){Optional<Parish> f=parishes.findById(id);if(f.isEmpty())return error(HttpStatus.NOT_FOUND,"Parish not found");if(in.getDeaneryId()!=null&&!deaneries.existsById(in.getDeaneryId()))return error(HttpStatus.BAD_REQUEST,"Deanery not found");if(!validPriest(in.getParishPriestId())||!validPriest(in.getAssistantPriestId()))return error(HttpStatus.BAD_REQUEST,"Priest IDs must refer to existing priests");if(in.getCatholicCount()!=null&&in.getCatholicCount()<0)return error(HttpStatus.BAD_REQUEST,"catholicCount cannot be negative");Parish p=f.get();if(!blank(in.getName())){if(parishes.findAll().stream().anyMatch(existing->!Objects.equals(existing.getId(),id)&&existing.getName()!=null&&existing.getName().equalsIgnoreCase(in.getName().trim())))return error(HttpStatus.CONFLICT,"A parish with this name already exists. Parish names must be unique.");p.setName(in.getName().trim());p.setSlug(uniqueSlug(in.getName(),id));}if(in.getDeaneryId()!=null)p.setDeaneryId(in.getDeaneryId());if(in.getParishPriestId()!=null)p.setParishPriestId(in.getParishPriestId());if(in.getAssistantPriestId()!=null)p.setAssistantPriestId(in.getAssistantPriestId());if(in.getAddress()!=null)p.setAddress(in.getAddress());if(in.getLatitude()!=null)p.setLatitude(in.getLatitude());if(in.getLongitude()!=null)p.setLongitude(in.getLongitude());if(in.getPhone()!=null)p.setPhone(in.getPhone());if(in.getEmail()!=null)p.setEmail(in.getEmail());if(in.getYearEstablished()!=null)p.setYearEstablished(in.getYearEstablished());if(in.getImageUrl()!=null)p.setImageUrl(in.getImageUrl());if(in.getFacebookPageUrl()!=null)p.setFacebookPageUrl(in.getFacebookPageUrl());if(in.getCatholicCount()!=null)p.setCatholicCount(in.getCatholicCount());return ResponseEntity.ok(dto(parishes.save(p)));}
    @DeleteMapping("/{id}") @Transactional public ResponseEntity<?> delete(@PathVariable Long id){if(!parishes.existsById(id))return error(HttpStatus.NOT_FOUND,"Parish not found");users.findByParishId(id).ifPresent(admin->{admin.setParishId(null);users.save(admin);});massTimes.findByParishId(id).forEach(massTimes::delete);priests.findByParishId(id).forEach(p->{p.setParishId(null);priests.save(p);});parishes.deleteById(id);return ResponseEntity.ok(Map.of("message","Parish deleted","id",id));}
    @GetMapping("/{id}/mass-times") public ResponseEntity<?> massTimes(@PathVariable Long id){if(!parishes.existsById(id))return error(HttpStatus.NOT_FOUND,"Parish not found");return ResponseEntity.ok(this.massTimes.findByParishId(id));}
    private void copy(Parish in,Parish p){p.setName(in.getName().trim());p.setDeaneryId(in.getDeaneryId());p.setParishPriestId(in.getParishPriestId());p.setAssistantPriestId(in.getAssistantPriestId());p.setAddress(in.getAddress());p.setLatitude(in.getLatitude());p.setLongitude(in.getLongitude());p.setPhone(in.getPhone());p.setEmail(in.getEmail());p.setYearEstablished(in.getYearEstablished());p.setImageUrl(in.getImageUrl());p.setFacebookPageUrl(in.getFacebookPageUrl());if(in.getCatholicCount()!=null)p.setCatholicCount(in.getCatholicCount());}
    private String uniqueSlug(String name,Long currentId){String base=Normalizer.normalize(name,Normalizer.Form.NFD).replaceAll("\\p{M}","").toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+","-").replaceAll("^-|-$","");if(base.isBlank())base="parish";String candidate=base;int n=2;while(slugTaken(candidate,currentId))candidate=base+"-"+n++;return candidate;}
    private boolean slugTaken(String slug,Long currentId){for(Parish p:parishes.findAll())if(Objects.equals(p.getSlug(),slug)&&!Objects.equals(p.getId(),currentId))return true;return false;}
    private boolean validPriest(Long id){return id==null||priests.existsById(id);}private boolean blank(String s){return s==null||s.trim().isEmpty();}private ResponseEntity<Map<String,String>> error(HttpStatus s,String m){return ResponseEntity.status(s).body(Map.of("error",m));}
    private Map<String,Object> dto(Parish p){Map<String,Object> m=new LinkedHashMap<>();m.put("id",p.getId());m.put("deaneryId",p.getDeaneryId());m.put("name",p.getName());m.put("slug",p.getSlug());m.put("parishPriestId",p.getParishPriestId());m.put("assistantPriestId",p.getAssistantPriestId());m.put("address",p.getAddress());m.put("latitude",p.getLatitude());m.put("longitude",p.getLongitude());m.put("phone",p.getPhone());m.put("email",p.getEmail());m.put("yearEstablished",p.getYearEstablished());m.put("imageUrl",p.getImageUrl());m.put("facebookPageUrl",p.getFacebookPageUrl());m.put("catholicCount",p.getCatholicCount()==null?0L:p.getCatholicCount());return m;}
}
